-- 45_mentorship.sql — SDBI B-10b m1 import: legacy RTL mentorship domain -> 4 sys.* tables (S970).
-- RTL-only (legacy tenant 0c54b84a -> v5 RTL 86ba7a65). Employee-centric (I14): mentor/mentee resolve via
--   sys_users.user_external_code='LEGACY_EMP::'||employees.id; unresolved -> FK NULL + legacy id in *_metadata.
-- Skill FK resolves via the ESCO-URI bridge (legacy esco_skills.uri -> sys_skills.skill_esco_uri).
-- Data baked as VALUES (CI-reproducible). Idempotent: ON CONFLICT (tenant, natural_key) DO NOTHING.
-- Expected landed: programs 5 / pairings 63 / sessions 150 / match_scores 30.
BEGIN;

-- §1 — programs (status/type lowercase -> UPPER)
WITH src(lid,name,descr,ptype,status,duration,maxp,focus,elig,sdate,edate) AS (VALUES
  ('446c0994-a455-4386-8e17-13269cb4a30e','Digital Transformation Champions','Equipping employees with digital skills and mindset through guidance from tech-savvy mentors. Focus on fintech innovations and digital customer experience.','technical','active','6','35','{"Digital Banking","Fintech Innovation","Data Analytics","Customer Experience"}',NULL,'2025-02-01',NULL),
  ('45685c35-7dec-43c9-ab40-7a8fc985d8fa','Women in Banking Leadership','An empowering program dedicated to advancing women in senior banking roles through strategic mentorship, networking, and career development.','dei','active','12','40','{"Career Advancement","Executive Networking","Work-Life Integration","Personal Branding"}',NULL,'2024-06-01',NULL),
  ('6e8b9809-747b-45c7-b8e1-8a09c8ca5687','Leadership Excellence Program','A comprehensive 12-month program designed to develop the next generation of banking leaders. Participants are paired with senior executives to build strategic thinking, decision-making, and team management skills.','leadership','active','12','30','{"Strategic Leadership","Executive Presence","Change Management","Business Development"}',NULL,'2024-09-01',NULL),
  ('9d0ff24c-77a9-4d01-adbb-79f867f80b97','Technical Banking Mastery','Connect junior analysts with experienced professionals to develop deep expertise in financial products, risk modeling, and regulatory frameworks.','technical','active','6','50','{"Risk Analysis","Financial Modeling","Regulatory Compliance","Product Knowledge"}',NULL,'2025-01-01',NULL),
  ('ef71e2dc-7176-4bff-a10a-e6a2e429bc9d','New Manager Accelerator','Supporting first-time managers in their transition from individual contributors to people leaders. Focus on coaching, feedback delivery, and team dynamics.','management','active','9','25','{"People Management","Performance Coaching","Conflict Resolution","Team Building"}',NULL,'2024-10-15',NULL)
)
INSERT INTO sys.sys_mentorship_programs
