   program_start_date, program_end_date, program_metadata)
SELECT '86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid, 'LEGACY_MPROG::'||src.lid, src.name, src.descr,
  upper(src.ptype), upper(src.status), src.duration::int, src.maxp::int, src.focus::text[],
  COALESCE(src.elig::jsonb,'{}'::jsonb), src.sdate::date, src.edate::date,
  jsonb_build_object('legacy_program_id', src.lid)
FROM src
ON CONFLICT (program_tenant_id, program_natural_key) DO NOTHING;

