INSERT INTO sys.sys_mentorships
  (mentorship_tenant_id, mentorship_natural_key, mentorship_program_id, mentorship_mentor_user_id,
   mentorship_mentee_user_id, mentorship_status, mentorship_focus_areas, mentorship_meeting_frequency,
   mentorship_goals, mentorship_match_score, mentorship_start_date, mentorship_end_date, mentorship_notes, mentorship_metadata)
SELECT '86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid, 'LEGACY_MENT::'||src.lid, p.program_id, mentor.user_id, mentee.user_id,
  upper(src.status), src.focus::text[],
  CASE lower(src.freq) WHEN 'bi-weekly' THEN 'BI_WEEKLY' WHEN 'biweekly' THEN 'BI_WEEKLY' WHEN 'weekly' THEN 'WEEKLY'
       WHEN 'monthly' THEN 'MONTHLY' WHEN 'quarterly' THEN 'QUARTERLY' ELSE 'AD_HOC' END,
  src.goals::text[], src.score::numeric, src.sdate::date, src.edate::date, src.notes,
  jsonb_strip_nulls(jsonb_build_object('legacy_mentorship_id', src.lid, 'legacy_meeting_frequency', src.freq,
    'unresolved_mentor', CASE WHEN mentor.user_id IS NULL THEN src.mentor_lid END,
    'unresolved_mentee', CASE WHEN mentee.user_id IS NULL THEN src.mentee_lid END,
    'legacy_program_id', CASE WHEN p.program_id IS NULL THEN src.plid END))
FROM src
LEFT JOIN sys.sys_mentorship_programs p ON p.program_natural_key='LEGACY_MPROG::'||src.plid AND p.program_tenant_id='86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid
LEFT JOIN sys.sys_users mentor ON mentor.user_external_code='LEGACY_EMP::'||src.mentor_lid
LEFT JOIN sys.sys_users mentee ON mentee.user_external_code='LEGACY_EMP::'||src.mentee_lid
ON CONFLICT (mentorship_tenant_id, mentorship_natural_key) DO NOTHING;

