INSERT INTO sys.sys_mentorship_sessions
  (session_tenant_id, session_natural_key, session_mentorship_id, session_date, session_duration_minutes,
   session_status, session_topics, session_notes, session_rating, session_metadata)
SELECT '86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid, 'LEGACY_MSESS::'||src.lid, m.mentorship_id, src.sdate::timestamptz,
  src.duration::int, upper(src.status), src.topics::text[], src.notes, src.rating::int,
  jsonb_build_object('legacy_session_id', src.lid, 'tz_assumption','UTC')
FROM src
JOIN sys.sys_mentorships m ON m.mentorship_natural_key='LEGACY_MENT::'||src.ment_lid
ON CONFLICT (session_tenant_id, session_natural_key) DO NOTHING;

