INSERT INTO sys.sys_mentor_match_scores
  (match_tenant_id, match_natural_key, match_mentee_user_id, match_mentor_user_id, match_skill_id, match_skill_name,
   match_mentee_level, match_mentor_level, match_score, match_factors, match_is_recommended, match_recommendation_rank,
   match_expires_at, match_metadata)
SELECT '86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid, 'LEGACY_MMS::'||src.lid, mentee.user_id, mentor.user_id, sk.skill_id,
  src.sname, src.mlevel::numeric, src.tlevel::numeric, src.score::numeric, COALESCE(src.factors::jsonb,'{}'::jsonb),
  src.is_rec::boolean, src.rank::int, src.expires::timestamptz,
  jsonb_strip_nulls(jsonb_build_object('legacy_match_id', src.lid, 'legacy_esco_uri', src.esco_uri,
    'unresolved_mentor', CASE WHEN mentor.user_id IS NULL THEN src.mentor_lid END,
    'unresolved_mentee', CASE WHEN mentee.user_id IS NULL THEN src.mentee_lid END))
FROM src
LEFT JOIN sys.sys_users mentee ON mentee.user_external_code='LEGACY_EMP::'||src.mentee_lid
LEFT JOIN sys.sys_users mentor ON mentor.user_external_code='LEGACY_EMP::'||src.mentor_lid
LEFT JOIN sys.sys_skills sk ON sk.skill_esco_uri=src.esco_uri
ON CONFLICT (match_tenant_id, match_natural_key) DO NOTHING;

-- §5 — reconciliation registry (classify the 4 new tables)
INSERT INTO sys.sys_reconciliation_registry
  (reconciliation_registry_table_name, reconciliation_registry_bucket, reconciliation_registry_declared_status,
   reconciliation_registry_legacy_source, reconciliation_registry_legacy_source_rows, reconciliation_registry_rationale)
VALUES
  ('sys_mentorship_programs','A','IMPORT','mentorship_programs',12,'[S970 SDBI m1] Mentorship program catalog; RTL-only import (5 of 12 legacy rows).'),
  ('sys_mentorships','A','IMPORT','mentorships',124,'[S970 SDBI m1] Mentor-mentee pairings; RTL-only (63 of 124); employee-centric LEGACY_EMP.'),
  ('sys_mentorship_sessions','A','IMPORT','mentorship_sessions',355,'[S970 SDBI m1] Session event log; RTL-only (150 of 355); CASCADE child of pairings.'),
  ('sys_mentor_match_scores','A','IMPORT','mentor_match_scores',30,'[S970 SDBI m1] Pre-match scoring; all 30 RTL; skill via ESCO-URI bridge.')
ON CONFLICT (reconciliation_registry_table_name) DO NOTHING;

DO $post$
DECLARE p int; m int; s int; x int;
BEGIN
  SELECT count(*) INTO p FROM sys.sys_mentorship_programs;
  SELECT count(*) INTO m FROM sys.sys_mentorships;
  SELECT count(*) INTO s FROM sys.sys_mentorship_sessions;
  SELECT count(*) INTO x FROM sys.sys_mentor_match_scores;
  RAISE NOTICE '45_mentorship: programs=% pairings=% sessions=% match_scores=% (expect 5/63/150/30)', p, m, s, x;
  IF p<>5 OR m<>63 OR s<>150 OR x<>30 THEN
    RAISE EXCEPTION '45_mentorship: count mismatch p=% m=% s=% x=%', p, m, s, x;
  END IF;
END $post$;
COMMIT;
